begin;
set local timezone='America/Bahia';
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('b1192000-0000-4000-8000-000000000001','authenticated','authenticated','field-security-a@example.test','',now(),'{}','{"name":"Field Security A","company_name":"Field Security A"}',now(),now()),
('b1192000-0000-4000-8000-000000000002','authenticated','authenticated','field-security-b@example.test','',now(),'{}','{"name":"Field Security B","company_name":"Field Security B"}',now(),now()),
('b1192000-0000-4000-8000-000000000003','authenticated','authenticated','field-security-tech@example.test','',now(),'{}','{"name":"Field Technician","company_name":"Field Technician"}',now(),now());
update public.profiles set company_id=(select company_id from public.profiles where auth_user_id='b1192000-0000-4000-8000-000000000001'),role='producao' where auth_user_id='b1192000-0000-4000-8000-000000000003';
select set_config('request.jwt.claims','{"sub":"b1192000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('fs.company',private.current_company_id(),true);
select set_config('fs.manager',(select id from public.profiles where auth_user_id=auth.uid()),true);
select set_config('fs.tech',(select id from public.profiles where auth_user_id='b1192000-0000-4000-8000-000000000003'),true);
insert into private.saas_billing_qa_tenants values(current_setting('fs.company'),'Field Security Synthetic QA');
create function pg_temp.fs_billing() returns void language plpgsql security definer set search_path='' as $$
declare command jsonb;claims text:=current_setting('request.jwt.claims');begin
 command:=public.saas_billing_prepare('start_trial',(select jsonb_build_object('revision',0,'plan_id',id,'plan_revision',revision,'cycle','monthly') from public.saas_plans where code='qa-essential'),gen_random_uuid());
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 perform public.saas_billing_event(jsonb_build_object('command_id',command->>'command_id','event_id','mock-billing:'||(command->>'command_id'),'sequence',(command->>'revision')::integer,'state','confirmed_qa'));
 perform set_config('request.jwt.claims',claims,true);
end $$;
grant execute on function pg_temp.fs_billing() to authenticated;
insert into public.customers(id,company_id,name,document,phone,email,address,tags,notes) values('is-customer',private.current_company_id(),'Cliente de segurança QA','','81900000000','','{"street":"Rua Imutável","number":"10","city":"Recife","state":"PE"}','{}','QA');
insert into public.products(id,company_id,name,pricing_type,base_cost,sales_price,stock_controlled,current_stock,min_stock) values('is-material',private.current_company_id(),'Material segurança QA','linear',2,5,true,10,0);
insert into public.orders(id,company_id,customer_id,customer_name,number,status,total_amount,paid_amount,payment_status,shipping_cost,deadline,notes) values('is-order',private.current_company_id(),'is-customer','Cliente de segurança QA','PED-119S','producao',100,0,'pendente',0,now()+interval '2 days','QA');
insert into public.order_items(id,order_id,product_name,quantity,unit_price,total_price,details) values('is-item','is-order','Serviço de segurança QA',1,100,100,'{}');
create function pg_temp.fs_payload(kind text default 'measurement') returns jsonb language sql as $$select jsonb_build_object('order_id','is-order','order_item_id','is-item','service_type',kind,'title','Serviço de segurança QA','assigned_profile_id',current_setting('fs.manager'),'team',jsonb_build_array(current_setting('fs.tech')),'address','{"street":"Rua Imutável","number":"10","city":"Recife","state":"PE"}'::jsonb,'checklist','[]'::jsonb)$$;
create function pg_temp.fs_action(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.field_service_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at) from public.field_services where id=current_setting('fs.id')::uuid)||patch)$$;
grant execute on function pg_temp.fs_payload(text),pg_temp.fs_action(text,jsonb) to authenticated;
set local role authenticated;
select set_config('fs.id',public.field_service_command('b1192000-0000-4000-8000-000000000010','save',pg_temp.fs_payload())->>'id',true);
select is(public.field_service_command('b1192000-0000-4000-8000-000000000010','save',pg_temp.fs_payload())->>'id',current_setting('fs.id'),'same nonce replays its receipt');
select is((select count(*) from public.field_services),1::bigint,'replay creates one service');
select throws_like($$select public.field_service_command('b1192000-0000-4000-8000-000000000010','save',pg_temp.fs_payload()||'{"title":"Conteúdo diferente"}')$$,'%Chave reutilizada%','same nonce cannot change payload');
select throws_like($$select public.field_service_command(gen_random_uuid(),'save',pg_temp.fs_payload()||'{"company_id":"forged"}')$$,'%Sem permissão%','browser never controls company');
select throws_like($$select public.field_service_command(gen_random_uuid(),'save',pg_temp.fs_payload()||'{"assigned_profile_id":"not-a-profile"}')$$,'%Técnico não elegível%','unknown assignee denied');
select throws_like($$select public.field_service_command(gen_random_uuid(),'transition',jsonb_build_object('id',current_setting('fs.id'),'updated_at','2020-01-01','status','traveling'))$$,'%Serviço mudou%','stale version denied before mutation');
select throws_like($$update public.field_services set title='Forged direct write'$$,'%permission denied%','direct service DML denied');
select throws_like($$select public.save_order_with_items_and_production((select to_jsonb(o)||'{"total_amount":200}'::jsonb from public.orders o where id='is-order'),(select jsonb_agg(to_jsonb(i)||'{"quantity":2,"total_price":200}'::jsonb) from public.order_items i where order_id='is-order'),(select updated_at from public.orders where id='is-order'))$$,'%histórico externo%','upstream technical item preserved');
select lives_ok($$select public.save_order_with_items_and_production((select to_jsonb(o) from public.orders o where id='is-order'),(select jsonb_agg(to_jsonb(i)||jsonb_build_object('details',i.details||'{"notes":"Observação operacional editável QA"}'::jsonb)) from public.order_items i where order_id='is-order'),(select updated_at from public.orders where id='is-order'))$$,'canonical Order UPSERT keeps operational item notes editable');
select throws_like($$select pg_temp.fs_action('transition','{"status":"running"}')$$,'%Transição inválida%','draft cannot skip travel and arrival');
select throws_like($$select pg_temp.fs_action('schedule',jsonb_build_object('start',now(),'end',now()-interval '1 hour'))$$,'%janela%','invalid appointment denied');
select lives_ok($$select pg_temp.fs_action('schedule',jsonb_build_object('start',now()+interval '1 day','end',now()+interval '1 day 1 hour'))$$,'canonical appointment created');
select lives_ok($$select pg_temp.fs_action('material_add','{"product_id":"is-material","quantity":0.000003}')$$,'six-place physical material planned');
select throws_like($$select unit_cost from public.field_service_materials$$,'%permission denied%','direct SELECT never exposes internal unit cost');
select set_config('fs.material',(select id::text from public.field_service_materials where service_id=current_setting('fs.id')::uuid),true);
select lives_ok($$select pg_temp.fs_action('material_take',jsonb_build_object('material_id',current_setting('fs.material'),'quantity',0.000003))$$,'take six-place amount');
select lives_ok($$select pg_temp.fs_action('material_settle',jsonb_build_object('material_id',current_setting('fs.material'),'consumed',0.000002,'returned',0.000001))$$,'settle six-place amount');
select is((select current_stock from public.products where id='is-material'),9.999998::numeric,'fractional stock reconciles exactly');
select lives_ok($$select pg_temp.fs_action('cost_save','{"kind":"parking","description":"Estacionamento QA","planned":10,"actual":8}')$$,'financial fact saved explicitly');
select set_config('fs.cost',(select id::text from public.field_service_costs where service_id=current_setting('fs.id')::uuid),true);
select is((select count(*) from public.financial_transactions),0::bigint,'saving cost creates no revenue or payable');
select throws_like($$select pg_temp.fs_action('cost_save','{"kind":"third_party","description":"Terceiro sem OT","planned":1,"actual":1}')$$,'%OT canônica%','outsourcing uses canonical OT');
reset role;
insert into public.role_permissions(company_id,path,roles) values(current_setting('fs.company'),'/field-services/manage','{}'),(current_setting('fs.company'),'/field-services/execute','{}') on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select throws_like($$select public.field_service_command('b1192000-0000-4000-8000-000000000010','save',pg_temp.fs_payload())$$,'%Sem permissão atual%','nonce replay rechecks revoked management permission');
reset role;
delete from public.role_permissions where company_id=current_setting('fs.company') and path in('/field-services/manage','/field-services/execute');
select set_config('request.jwt.claims','{"sub":"b1192000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is(jsonb_array_length(public.field_service_source(p_id=>current_setting('fs.id')::uuid)->'costs'),0,'technician receives no financial cost projection');
select ok(not((public.field_service_source(p_id=>current_setting('fs.id')::uuid)->'materials'->0)?'unit_cost'),'technician material projection excludes unit cost');
select throws_like($$select pg_temp.fs_action('cost_save','{"kind":"travel","description":"Acesso indevido","actual":1}')$$,'%Sem permissão%','technician cannot record financial costs');
select throws_like($$select pg_temp.fs_action('reopen','{"reason":"Acesso indevido"}')$$,'%Reabertura exige gestor%','technician cannot reopen');
select lives_ok($$select pg_temp.fs_action('transition','{"status":"traveling"}')$$,'assigned technician can leave');
select lives_ok($$select pg_temp.fs_action('impediment','{"kind":"absent","reason":"Cliente QA ausente no local"}')$$,'assigned technician records impediment');
select lives_ok($$select pg_temp.fs_action('reschedule',jsonb_build_object('start',now()+interval '2 days','end',now()+interval '2 days 1 hour','reason','Nova visita sintética QA'))$$,'blocked service reschedules its single canonical appointment');
select is((select count(*) from public.agenda_events),0::bigint,'field scheduling never creates a duplicate manual calendar event');
reset role;
select set_config('request.jwt.claims','{"sub":"b1192000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select pg_temp.fs_action('transition','{"status":"traveling"}')$$,'manager leaves for measurement before production ready');
select lives_ok($$select pg_temp.fs_action('transition','{"status":"on_site"}')$$,'arrive after reschedule');
select lives_ok($$select pg_temp.fs_action('transition','{"status":"running"}')$$,'run after reschedule');
select set_config('fs.photo',(pg_temp.fs_action('file_reserve',jsonb_build_object('kind','after','sha256',repeat('a',64),'bytes',100,'mime','image/jpeg','caption','Foto sintética QA'))#>>'{file,id}'),true);
select throws_like($$select pg_temp.fs_action('complete')$$,'%uploads pendentes%','pending upload blocks conclusion');
select throws_like($$select public.field_service_file_access(current_setting('fs.photo')::uuid)$$,'%Sem permissão%','pending object cannot be signed');
select throws_like($$select public.field_service_commit_upload(current_setting('fs.photo')::uuid,'b1192000-0000-4000-8000-000000000001',repeat('a',64),100)$$,'%permission denied%','browser cannot forge upload finalization');
reset role;
insert into storage.objects(bucket_id,name) select 'field-service-evidence',path from public.field_service_evidence where id=current_setting('fs.photo')::uuid;
select set_config('request.jwt.claims','{"sub":"b1192000-0000-4000-8000-000000000001","role":"service_role"}',true);
set local role service_role;
select lives_ok($$select public.field_service_commit_upload(current_setting('fs.photo')::uuid,'b1192000-0000-4000-8000-000000000001',repeat('a',64),100)$$,'trusted server finalizes the verified upload');
select lives_ok($$select public.field_service_commit_upload(current_setting('fs.photo')::uuid,'b1192000-0000-4000-8000-000000000001',repeat('a',64),100)$$,'trusted upload finalization is idempotent');
reset role;
select is((select count(*) from public.field_service_events where service_id=current_setting('fs.id')::uuid and action='evidence_added'),1::bigint,'idempotent finalization audits once');
select set_config('request.jwt.claims','{"sub":"b1192000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_like($$select pg_temp.fs_action('file_reserve',jsonb_build_object('kind','signature','sha256',repeat('b',64),'bytes',100,'mime','image/png','acceptance','{"name":"QA","consent":false}'::jsonb))$$,'%nome e consentimento%','signature requires clear consent');
select set_config('fs.signature',(pg_temp.fs_action('file_reserve',jsonb_build_object('kind','signature','sha256',repeat('b',64),'bytes',100,'mime','image/png','acceptance','{"name":"Cliente QA","consent":true,"unexpected":"must disappear"}'::jsonb))#>>'{file,id}'),true);
select ok(not((select acceptance from public.field_service_evidence where id=current_setting('fs.signature')::uuid)?'unexpected'),'acceptance metadata is normalized');
select throws_like($$select pg_temp.fs_action('file_reserve',jsonb_build_object('kind','signature','sha256',repeat('b',64),'bytes',100,'mime','image/png','acceptance','{"name":"Cliente QA","consent":true}'::jsonb))$$,'%no máximo um aceite%','one signature per execution');
select lives_ok($$select pg_temp.fs_action('file_remove',jsonb_build_object('evidence_id',current_setting('fs.signature'),'reason','Remoção sintética autorizada QA'))$$,'controlled pending removal is audited');
reset role;
select set_config('request.jwt.claims','{"sub":"b1192000-0000-4000-8000-000000000001","role":"service_role"}',true);
set local role service_role;
select throws_like($$select public.field_service_commit_upload(current_setting('fs.signature')::uuid,'b1192000-0000-4000-8000-000000000001',repeat('b',64),100)$$,'%não pode ser finalizado%','removed upload cannot be resurrected');
reset role;
select set_config('request.jwt.claims','{"sub":"b1192000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select pg_temp.fs_action('complete','{"note":"Conclusão segura QA"}')$$,'execution completes with verified evidence');
select lives_ok($$select pg_temp.fs_action('cost_save','{"kind":"toll","description":"Pedágio conferido após execução","planned":4,"actual":3}')$$,'financial settlement remains available after technical completion');
select set_config('fs.account',public.finance_command(gen_random_uuid(),'account_create','{"name":"Field QA Bank","kind":"bank","amount":0}')#>>'{account,id}',true);
select set_config('fs.category',public.finance_command(gen_random_uuid(),'category_create','{"name":"Field QA Expense","type":"despesa"}')->>'id',true);
select lives_ok($$select pg_temp.fs_action('cost_export',jsonb_build_object('cost_id',current_setting('fs.cost'),'account_id',current_setting('fs.account'),'category_id',current_setting('fs.category'),'date',current_date+10))$$,'explicit action creates canonical payable');
select lives_ok($$select pg_temp.fs_action('cost_export',jsonb_build_object('cost_id',current_setting('fs.cost'),'account_id',current_setting('fs.account'),'category_id',current_setting('fs.category'),'date',current_date+10))$$,'another nonce never creates a second obligation');
select is((select count(*) from public.financial_transactions where type='despesa'),1::bigint,'one canonical obligation');
select is((select coalesce(sum(case type when 'receita' then amount else -amount end),0) from public.financial_transactions where account_id=current_setting('fs.account')::uuid and entry_role='movement' and status='pago'),0::numeric,'creating obligation makes no automatic payment');
select is((select total_amount from public.orders where id='is-order'),100::numeric,'operational costs preserve original Order price');
select lives_ok($$select pg_temp.fs_action('cost_cancel',jsonb_build_object('cost_id',current_setting('fs.cost'),'reason','Encerramento sintético QA'))$$,'unpaid obligation cancels through canonical finance');
select set_config('fs.previous_financial',(select financial_id from public.field_service_costs where id=current_setting('fs.cost')::uuid),true);
select throws_like($$select pg_temp.fs_action('cost_export',jsonb_build_object('cost_id',current_setting('fs.cost'),'account_id',current_setting('fs.account'),'category_id',current_setting('fs.category'),'date',current_date+10))$$,'%Corrija o custo%','cancelled financial link never masquerades as an active obligation');
select lives_ok($$select pg_temp.fs_action('cost_save',jsonb_build_object('cost_id',current_setting('fs.cost'),'kind','parking','description','Custo QA corrigido','planned',10,'actual',12,'reason','Correção explícita após cancelamento'))$$,'cancelled cost can be corrected to a new actual amount');
select ok((select financial_id is null and financial_history ? current_setting('fs.previous_financial') from public.field_service_costs where id=current_setting('fs.cost')::uuid),'old link is preserved as history, current link cleared');
select lives_ok($$select pg_temp.fs_action('cost_export',jsonb_build_object('cost_id',current_setting('fs.cost'),'account_id',current_setting('fs.account'),'category_id',current_setting('fs.category'),'date',current_date+10))$$,'corrected cost creates a new canonical obligation');
select lives_ok($$select pg_temp.fs_action('cost_export',jsonb_build_object('cost_id',current_setting('fs.cost'),'account_id',current_setting('fs.account'),'category_id',current_setting('fs.category'),'date',current_date+10))$$,'repeating corrected export does not duplicate the new obligation');
select is((select count(*) from public.financial_transactions where type='despesa' and cancelled_at is null),1::bigint,'exactly one active corrected obligation');
select is((select amount from public.financial_transactions where id=(select financial_id from public.field_service_costs where id=current_setting('fs.cost')::uuid)),12::numeric,'corrected obligation uses current actual amount');
select lives_ok($$select pg_temp.fs_action('cost_cancel',jsonb_build_object('cost_id',current_setting('fs.cost'),'reason','Encerrar obrigação corrigida QA'))$$,'corrected obligation cancels through Finance');
select lives_ok($$select pg_temp.fs_action('cost_save',jsonb_build_object('cost_id',current_setting('fs.cost'),'kind','parking','description','Custo QA encerrado','planned',0,'actual',0,'reason','Correção sintética após cancelamento'))$$,'cancelled obligation permits explicit audited cost correction');
select lives_ok($$select pg_temp.fs_action('reopen','{"reason":"Nova execução sem apagar conclusão QA"}')$$,'authorized reopening creates a new run');
select lives_ok($$select pg_temp.fs_action('material_add','{"product_id":"is-material","quantity":0.000001}')$$,'reopened execution can plan the same material independently');
select is((select count(*) from public.field_service_materials where service_id=current_setting('fs.id')::uuid),2::bigint,'each execution retains its own material row');
select is((select current_stock from public.products where id='is-material'),9.999998::numeric,'reopening does not reverse the previous physical consumption');
select throws_like($$select pg_temp.fs_action('material_settle',jsonb_build_object('material_id',current_setting('fs.material'),'consumed',0,'returned',0.000001))$$,'%execução atual%','old execution cannot silently receive new consumption');
select lives_ok($$select pg_temp.fs_action('material_add','{"product_id":"is-material","quantity":0.000002}')$$,'planned total can be revised without creating another row');
select is((select count(*) from public.field_service_materials where service_id=current_setting('fs.id')::uuid and run=2),1::bigint,'planning revision does not duplicate a material row');
select throws_like($$select pg_temp.fs_action('material_add','{"product_id":"is-material","quantity":0.0000001}')$$,'%seis casas%','planning never silently rounds beyond physical precision');
select lives_ok($$select pg_temp.fs_action('file_remove',jsonb_build_object('evidence_id',current_setting('fs.photo'),'reason','Remoção controlada e auditada QA'))$$,'historical evidence removal has an explicit tombstone');
select is((select snapshot#>>'{evidence,0,state}' from public.field_service_completions where service_id=current_setting('fs.id')::uuid and run=1),'ready','completion snapshot remains immutable after removal');
select is((select state from public.field_service_evidence where id=current_setting('fs.photo')::uuid),'removed','current evidence projection records removal for historical PDF');
select throws_like($$select public.field_service_file_access(current_setting('fs.photo')::uuid)$$,'%Sem permissão%','removed image cannot receive a new signed URL');
select lives_ok($$select pg_temp.fs_action('material_reverse',jsonb_build_object('material_id',current_setting('fs.material'),'reason','Concluir fixture de segurança QA'))$$,'inverse returns only net material');
select is((select current_stock from public.products where id='is-material'),10::numeric,'fixture returns exact original stock');
select lives_ok($$select pg_temp.fs_action('cancel','{"reason":"Encerrar serviço sintético QA"}')$$,'fixture service cancels without touching parent Order');
select set_config('fs.id',public.field_service_command(gen_random_uuid(),'save',pg_temp.fs_payload('installation'))->>'id',true);
select lives_ok($$select pg_temp.fs_action('schedule',jsonb_build_object('start',now(),'end',now()+interval '1 hour'))$$,'installation appointment created');
select throws_like($$select pg_temp.fs_action('transition','{"status":"traveling"}')$$,'%produção pronta%','installation cannot leave before production ready');
reset role;
insert into public.order_items(id,order_id,product_name,quantity,unit_price,total_price,details) values('is-other-item','is-order','Outro item QA',1,1,1,'{}');
insert into public.production_queue(id,company_id,order_id,order_number,order_item_id,product_name,status) values
('is-ready-production',current_setting('fs.company'),'is-order','PED-119S','is-item','Serviço de segurança QA','concluido'),
('is-other-production',current_setting('fs.company'),'is-order','PED-119S','is-other-item','Outro item QA','fila')
on conflict(company_id,order_item_id) do update set status=excluded.status;
set local role authenticated;
select lives_ok($$select pg_temp.fs_action('transition','{"status":"traveling"}')$$,'installation readiness uses its linked item, without waiting on unrelated production');
select is((select status from public.production_queue where id='is-other-production'),'fila','field execution does not advance unrelated production');
select lives_ok($$select pg_temp.fs_action('impediment','{"kind":"absent","reason":"Teste de escopo concluído QA"}')$$,'scoped installation can record impediment');
reset role;
update public.profiles set active=false where auth_user_id='b1192000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_like($$select pg_temp.fs_action('reschedule',jsonb_build_object('start',now(),'end',now()+interval '1 hour','reason','Reagendar com equipe inativa'))$$,'%ativos e elegíveis%','inactive team cannot be rescheduled');
select lives_ok($$select pg_temp.fs_billing()$$,'synthetic tenant enters QA plan without reports');
select is(public.field_service_source(p_id=>current_setting('fs.id')::uuid)#>>'{permissions,reports}','false','operational source reflects missing report entitlement');
select lives_ok($$select public.field_service_source(p_id=>current_setting('fs.id')::uuid)$$,'operational history remains readable without report feature');
select throws_like($$select public.field_service_source(p_id=>current_setting('fs.id')::uuid,p_reports=>true)$$,'%Recurso indisponível no plano%','explicit reports mode enforces canonical SaaS entitlement');
reset role;
select set_config('request.jwt.claims','{"sub":"b1192000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*) from public.field_services),0::bigint,'tenant B direct read denies all A services');
select is((select count(*) from public.field_service_evidence),0::bigint,'tenant B direct read denies evidence');
select throws_like($$select public.field_service_source(p_id=>current_setting('fs.id')::uuid)$$,'%indisponível%','tenant B cannot load another service');
select throws_like($$select public.field_service_file_access(current_setting('fs.photo')::uuid)$$,'%Sem permissão%','tenant B cannot sign another company object');
reset role;
select * from finish();rollback;
